1	/**
2	 * `?match08=1` — Screen 08 approved-picture test (2026-11-17, qa/match/08/NOTES.md).
3	 * REAL 3D proxy geometry of the Final Spin Chamber, solved from the user's approved Screen 08 and the locked game
4	 * camera (tools/match08/fit_proxies.py → assets/textures/match08/proj08.json): inlet pipe, gold arch, chamber walls,
5	 * door wall, floor/river plane, platform (top tilted toward the camera as painted), towel and the four half-dome spouts.
6	 * Every surface is textured by camera projection of the CLEAN environment-only artwork (Benny, HUD, coins removed;
7	 * qa/imageblaster/08/) from that locked camera, so the locked view shows the approved scenery and a moving camera sees
8	 * it on geometry (parallax). Surfaces the projector cannot see (behind props) get a plain fallback colour instead of
9	 * a smeared copy (projector depth test). The shader undoes the game's post chain (PROJ05_INVERSE) and takes no fog.
10	 * Without the switch nothing in this file runs and the game is unchanged.
11	 */
12	import * as THREE from 'three';
13	import { PROJ05_INVERSE, flag05 } from '../vfx/waterRibbon';
14	
15	interface Layout {
16	  camera: { matrixWorld: number[]; fov: number; size: [number, number] };
17	  floorY: number;
18	  chamber: { cx: number; cy: number; r: number; zBack: number; zDoor: number };
19	  arch: { z: number; outer: { cx: number; cy: number; r: number }; inner: { cx: number; cy: number; r: number }; depth: number };
20	  pipe: { cx: number; cy: number; r: number; z0: number; z1: number };
21	  backwall: { z: number; holeR: number };
22	  platform: { cx: number; cz: number; r: number; topY: number; rimBottomY: number; floorY: number; tiltDeg: number };
23	  towel: { cx: number; cz: number; w: number; h: number; y0: number; d: number };
24	  spouts: Record<string, { c: [number, number, number]; rx: number; ry: number }>;
25	}
26	
27	export interface Match08 {
28	  group: THREE.Group;
29	  /** the approved picture's splash ring around Benny (camera-facing card; Game places it at Benny + splashOffset) */
30	  splash: THREE.Mesh;
31	  splashOffset: THREE.Vector3;
32	  /** render the projector depth map once (needs the renderer); call after the group is in the scene */
33	  bakeDepth(renderer: THREE.WebGLRenderer): void;
34	  /** live post values for the inverse (exposure from the renderer, render size for the vignette inverse) */
35	  sync(renderer: THREE.WebGLRenderer, w: number, h: number): void;
36	}
37	
38	const VERT = /* glsl */ `
39	uniform mat4 uProjVP;
40	varying vec4 vProj;
41	varying vec3 vW;
42	varying vec3 vN;
43	void main() {
44	  vec4 wp = modelMatrix * vec4(position, 1.0);
45	  vProj = uProjVP * wp;
46	  vW = wp.xyz;
47	  vN = normalize(mat3(modelMatrix) * normal);
48	  gl_Position = projectionMatrix * viewMatrix * wp;
49	}`;
50	
51	const FRAG = /* glsl */ `
52	uniform sampler2D uPlate;
53	uniform sampler2D uDepth;
54	uniform float uUseDepth;
55	uniform vec2 uNearFar;
56	uniform vec3 uFallback;
57	uniform sampler2D uPatch;   // material patch cut from the approved artwork (wall slots / gold band / towel)
58	uniform float uPatchK;      // patch repeats per world unit
59	uniform vec3 uProjPos;      // projector (approved view) position
60	uniform vec4 uPjPost;
61	uniform vec2 uPjRes;
62	uniform sampler2D uFill;    // m08fill: world-anchored wall tile cut from the picture's near pipe wall (unwrap08.py)
63	uniform float uFillMode;    // 0 off (triplanar patch), 1 drum wall (around the chamber axis), 2 flat disc (x/y)
64	uniform vec2 uFillSize;     // tile size in world units (around, along)
65	uniform vec3 uDrum;         // chamber axis x, y and radius
66	uniform mat4 uProjVP;
67	uniform float uSwim;        // m08swim (floor only): the painted river's banks spread to cover Benny's whole swim lane
68	uniform sampler2D uRiv;     // 64 x 1: painted river centre x (r) and full width (g) along z
69	uniform vec4 uRivZ;         // z at texel 0, z at texel 63, lane half-width to cover, floor y
70	uniform sampler2D uOcc;     // m08occ (door wall only): plate with towel + platform painted out (occ08.py), alpha = usable
71	uniform float uOccOn;
72	uniform sampler2D uTMask;   // m08towelm (towel only): the painted towel's outline in plate coordinates (towelmask08.py)
73	uniform float uTMaskOn;
74	uniform vec4 uClipIn;       // m08far collar only: discard inside this x/y circle (the chamber's cross-section) ...
75	uniform vec4 uClipOut;      // ... and outside this one (the pushed arch's outline); w > 0.5 = on
76	uniform vec4 uCeil;         // m08ceil (door wall only): painted door centre x, y on the door plane, plane z, w > 0.5 = on
77	uniform vec4 uCeilW;        // m08ceil source window: angle start, angle width (rad), radius band start, end (world u)
78	varying vec4 vProj;
79	varying vec3 vW;
80	varying vec3 vN;
81	${PROJ05_INVERSE}
82	// triplanar, mirrored-repeat sampling of the patch: surfaces the approved picture never showed (or showed edge-on)
83	vec3 patchColor() {
84	  vec3 n = abs(normalize(vN)); n /= max(n.x + n.y + n.z, 1e-4);
85	  vec3 p = vW * uPatchK;
86	  return texture2D(uPatch, p.zy).rgb * n.x + texture2D(uPatch, p.xz).rgb * n.y + texture2D(uPatch, p.xy).rgb * n.z;
87	}
88	float linZ(float d) { float n = uNearFar.x, f = uNearFar.y; float z = d * 2.0 - 1.0; return 2.0 * n * f / (f + n - z * (f - n)); }
89	vec3 fillColor() {
90	  vec2 q;
91	  if (uFillMode < 1.5) {
92	    // angle from straight down: the wrap of atan lies under the floor, never seen
93	    float a = atan(vW.x - uDrum.x, -(vW.y - uDrum.y));
94	    float n = floor(6.2831853 * uDrum.z / uFillSize.x + 0.5);  // whole tiles around the drum: no seam
95	    q = vec2(a / 6.2831853 * n, vW.z / uFillSize.y);
96	  } else q = vW.xy / uFillSize;
97	  return texture2D(uFill, q).rgb;
98	}
99	// m08ceil: the painted end wall is concentric around the door (chrome rim, gold bulb ring, slot rows), so a door-wall point
100	// the approved view could not see (behind the arch ring: the ceiling above the door) takes the user's pixels from the SAME
101	// radius in a clean window of the painted wall beside the door (left of the door, between the spout cup and its stream),
102	// repeated (mirrored, a whole number of times around) by angle; beyond the window's slot band the slot rows repeat outward.
103	// The rings therefore continue across the old seam instead of meeting a generic tile.
104	vec3 ceilColor() {
105	  vec2 d = vW.xy - uCeil.xy;
106	  float r = length(d), a = atan(d.y, d.x);
107	  float fu = mod((a - uCeilW.x) / uCeilW.y, 2.0);
108	  float as = uCeilW.x + (fu < 1.0 ? fu : 2.0 - fu) * uCeilW.y;
109	  float rs = r;
110	  if (r > uCeilW.w) { float w2 = uCeilW.w - uCeilW.z, fr = mod(r - uCeilW.w, 2.0 * w2); rs = fr < w2 ? uCeilW.w - fr : uCeilW.z + (fr - w2); }
111	  vec4 q = uProjVP * vec4(uCeil.xy + rs * vec2(cos(as), sin(as)), uCeil.z, 1.0);
112	  return texture2D(uPlate, q.xy / q.w * 0.5 + 0.5).rgb;
113	}
114	vec2 riv(float z) {
115	  float f = clamp((z - uRivZ.x) / (uRivZ.y - uRivZ.x), 0.0, 1.0) * 63.0;
116	  float i0 = floor(f);
117	  vec2 a = texture2D(uRiv, vec2((i0 + 0.5) / 64.0, 0.5)).rg, b = texture2D(uRiv, vec2((min(i0 + 1.0, 63.0) + 0.5) / 64.0, 0.5)).rg;
118	  return mix(a, b, f - i0);
119	}
120	// m08swim: lateral remap of a floor point. The middle of the painted river stays as painted, its banks (water edge,
121	// foam) are spread out to the lane half-width, the floor beyond is pushed out and eased back over 2.5 u. World-anchored
122	// (depends on the floor point only) and faded in with the camera's distance from the approved viewpoint.
123	vec3 swimRemap(vec3 w, float mv) {
124	  vec2 r = riv(w.z);
125	  float hp = 0.5 * r.y, h = mix(hp, max(hp, uRivZ.z), mv);
126	  if (h <= hp + 1e-3) return w;
127	  float d = w.x - r.x, ad = abs(d), a = 0.45 * hp, e = h - hp, o;
128	  if (ad <= a) o = ad;
129	  else if (ad <= h) o = a + (ad - a) * (hp - a) / (h - a);
130	  else o = ad - e * max(0.0, 1.0 - (ad - h) / 2.5);
131	  return vec3(r.x + sign(d) * o, w.y, w.z);
132	}
133	void main() {
134	  if (uClipIn.w > 0.5 && (distance(vW.xy, uClipIn.xy) < uClipIn.z || distance(vW.xy, uClipOut.xy) > uClipOut.z)) discard;
135	  // m08towelm: the towel proxy is cut to the painted towel's outline (the depth bake does the same, so the door wall
136	  // behind receives the window pixels that the rectangle used to carry at towel depth)
137	  if (uTMaskOn > 0.5 && vProj.w > 0.0 && texture2D(uTMask, vProj.xy / vProj.w * 0.5 + 0.5).r < 0.5) discard;
138	  // m08fill fades in as the camera leaves the approved viewpoint (the approved view keeps its exact old pixels)
139	  vec3 pc = patchColor();
140	  if (uFillMode > 0.5) pc = mix(pc, fillColor(), smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)));
141	  if (uCeil.w > 0.5) pc = mix(pc, ceilColor(), smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)));
142	  vec3 t = pc;
143	  // stretch guard: the projection is used where the current view sees the surface no more face-on than the approved
144	  // view did (ratio of the two incidence cosines); in the approved view itself the ratio is 1 -> pure projection
145	  vec3 nn = normalize(vN);
146	  float cp = abs(dot(nn, normalize(uProjPos - vW))), cc = abs(dot(nn, normalize(cameraPosition - vW)));
147	  float keep = 1.0 - smoothstep(2.5, 6.0, cc / max(cp, 1e-3));
148	  vec4 pj = vProj;
149	  if (uSwim > 0.5) {
150	    float ms = smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos));
151	    if (ms > 0.0) pj = uProjVP * vec4(swimRemap(vW, ms), 1.0);
152	  }
153	  if (pj.w > 0.0) {
154	    vec3 ndc = pj.xyz / pj.w;
155	    vec2 uv = ndc.xy * 0.5 + 0.5;
156	    if (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
157	      float vis = 1.0;
158	      if (uUseDepth > 0.5) {
159	        float zf = linZ(ndc.z * 0.5 + 0.5);
160	        float zs = linZ(texture2D(uDepth, uv).r);
161	        vis = 1.0 - smoothstep(0.015 * zs, 0.04 * zs + 0.05, zf - zs);
162	        // m08fill: once the camera has left the approved viewpoint, a soft hand-over to the fill (5 x 5 taps over ~3 %
163	        // of the frame) instead of a hard shadow line; at the viewpoint itself the exact single-tap test (view unchanged)
164	        float mv = uFillMode > 0.5 ? smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)) : 0.0;
165	        if (mv > 0.0) {
166	          float sv = 0.0;
167	          for (int i = -2; i <= 2; i++) for (int j = -2; j <= 2; j++) {
168	            float zt = linZ(texture2D(uDepth, uv + vec2(float(i), float(j) * 0.5625) * 0.007).r);
169	            sv += 1.0 - smoothstep(0.015 * zt, 0.04 * zt + 0.05, zf - zt);
170	          }
171	          vis = mix(vis, smoothstep(0.0, 1.0, sv / 25.0), mv);
172	        }
173	      }
174	      // m08occ: what the approved view could not see behind the towel / platform comes from the occlusion plate (the
175	      // painted door / window continued), not from the fallback tile with its straight edges; off the viewpoint only
176	      vec3 base = pc;
177	      if (uOccOn > 0.5) {
178	        vec4 oc = texture2D(uOcc, uv);
179	        base = mix(pc, oc.rgb, oc.a * smoothstep(0.2, 1.5, distance(cameraPosition, uProjPos)));
180	      }
181	      t = mix(base, texture2D(uPlate, uv).rgb, vis * keep);
182	    }
183	  }
184	  gl_FragColor = vec4(pjInverse(t), 1.0);
185	}`;
186	
187	/** several (nu × nv) vertex grids f(u, v) → one indexed geometry (m08arch: fine tessellation for per-vertex pushes) */
188	function gridGeo(parts: [number, number, (u: number, v: number) => THREE.Vector3][]): THREE.BufferGeometry {
189	  const pos: number[] = [], idx: number[] = [];
190	  for (const [nu, nv, f] of parts) {
191	    const b = pos.length / 3;
192	    for (let j = 0; j <= nv; j++) for (let i = 0; i <= nu; i++) { const p = f(i / nu, j / nv); pos.push(p.x, p.y, p.z); }
193	    for (let j = 0; j < nv; j++) for (let i = 0; i < nu; i++) { const a = b + j * (nu + 1) + i, c = a + nu + 1; idx.push(a, c, a + 1, c, c + 1, a + 1); }
194	  }
195	  const g = new THREE.BufferGeometry();
196	  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); g.setIndex(idx); g.computeVertexNormals();
197	  return g;
198	}
199	
200	export async function buildMatch08(): Promise<Match08> {
201	  const L: Layout = await fetch(new URL('../../assets/textures/match08/proj08.json', import.meta.url).href).then((r) => r.json());
202	  const plate = await new THREE.TextureLoader().loadAsync(new URL('../../assets/textures/match08/plate08_hybrid.png', import.meta.url).href);
203	  plate.colorSpace = THREE.NoColorSpace; // raw display values: the shader inverts the post chain itself
204	  plate.minFilter = THREE.LinearMipmapLinearFilter;
205	  plate.anisotropy = 8;
206	
207	  // the projector = the locked game camera the picture was matched to
208	  const [W, H] = L.camera.size;
209	  const proj = new THREE.PerspectiveCamera(L.camera.fov, W / H, 0.2, 160);
210	  proj.matrixWorld.fromArray(L.camera.matrixWorld);
211	  proj.matrixWorld.decompose(proj.position, proj.quaternion, proj.scale);
212	  proj.matrixWorldInverse.copy(proj.matrixWorld).invert();
213	  proj.updateProjectionMatrix();
214	  const projVP = new THREE.Matrix4().multiplyMatrices(proj.projectionMatrix, proj.matrixWorldInverse);
215	
216	  const depthRT = new THREE.WebGLRenderTarget(1024, Math.round((1024 * H) / W), { depthBuffer: true });
217	  depthRT.depthTexture = new THREE.DepthTexture(depthRT.width, depthRT.height, THREE.UnsignedIntType);
218	  const shared = {
219	    uPlate: { value: plate },
220	    uDepth: { value: depthRT.depthTexture as THREE.Texture },
221	    uUseDepth: { value: 0 },
222	    uNearFar: { value: new THREE.Vector2(proj.near, proj.far) },
223	    uProjVP: { value: projVP },
224	    uPjPost: { value: new THREE.Vector4(0.86, 1.36, 1.15, 0.18) },
225	    uPjRes: { value: new THREE.Vector2(W, H) },
226	    uProjPos: { value: proj.position.clone() },
227	  };
228	  // material patches cut from the approved artwork (tools: qa/match/08/NOTES.md), mirrored so the tiling has no seams
229	  const loadPatch = async (name: string) => {
230	    const t = await new THREE.TextureLoader().loadAsync(new URL(`../../assets/textures/match08/patch_${name}.png`, import.meta.url).href);
231	    t.colorSpace = THREE.NoColorSpace; t.wrapS = t.wrapT = THREE.MirroredRepeatWrapping; t.anisotropy = 4; return t;
232	  };
233	  const [pWall, pGold, pTowel] = await Promise.all([loadPatch('wall'), loadPatch('gold'), loadPatch('towel')]);
234	  // `&m08fill=1` (scenery round): chamber surfaces the picture never showed get a world-anchored tile of the picture's
235	  // own wall (no mirrored kaleidoscope); see tools/match08/unwrap08.py and qa/match/08/scenery/NOTES.md
236	  const fill = flag05('m08fill');
237	  let fillTex: THREE.Texture | null = null, fillSize = new THREE.Vector2(1, 1);
238	  if (fill) {
239	    const FJ: { w: number; h: number } = await fetch(new URL('../../assets/textures/match08/fill_drum.json', import.meta.url).href).then((r) => r.json());
240	    fillTex = await new THREE.TextureLoader().loadAsync(new URL('../../assets/textures/match08/fill_drum.png', import.meta.url).href);
241	    fillTex.colorSpace = THREE.NoColorSpace; fillTex.wrapS = fillTex.wrapT = THREE.RepeatWrapping; fillTex.anisotropy = 8;
242	    // `&m08seam=1` (r6): the tile came from the NEAR pipe wall; on the chamber drum its slots looked denser than the painted
243	    // chamber wall beside them (a visible slot-size change at the hand-over) -> scale the tile (×m08seamk, default 1.6)
244	    const seamK = flag05('m08seam') ? Number(new URLSearchParams(location.search).get('m08seamk') ?? '') || 1.6 : 1;
245	    fillSize = new THREE.Vector2(FJ.w * seamK, FJ.h * seamK);
246	  }
247	  // `&m08swim=1` (scenery round r6): Benny can steer ±2.22 u (+ his body) off the course centre, but the painted river is
248	  // only 2–4 u wide over the first 8 u of the chamber, so hard steering put him on the purple floor. The floor material
249	  // spreads the painted river's banks to the whole reachable lane (river08.json centre / width), approved view unchanged.
250	  const swimOn = flag05('m08swim');
251	  const RV: { z: number[]; x: number[]; width: number[] } = await fetch(new URL('../../assets/textures/match08/river08.json', import.meta.url).href).then((r) => r.json());
252	  const rivData = new Float32Array(64 * 4);
253	  const rz0 = RV.z[0], rz1 = RV.z[RV.z.length - 1];
254	  for (let i = 0; i < 64; i++) {
255	    const z = rz0 + ((rz1 - rz0) * i) / 63;
256	    let k = 0; while (k < RV.z.length - 2 && RV.z[k + 1] > z) k++;
257	    const f = THREE.MathUtils.clamp((z - RV.z[k]) / (RV.z[k + 1] - RV.z[k]), 0, 1);
258	    rivData[i * 4] = RV.x[k] + (RV.x[k + 1] - RV.x[k]) * f;
259	    rivData[i * 4 + 1] = RV.width[k] + (RV.width[k + 1] - RV.width[k]) * f;
260	  }
261	  const rivTex = new THREE.DataTexture(rivData, 64, 1, THREE.RGBAFormat, THREE.FloatType);
262	  rivTex.minFilter = rivTex.magFilter = THREE.NearestFilter; rivTex.needsUpdate = true;
263	  const SWIM_HALF = Number(new URLSearchParams(location.search).get('m08swimw') ?? '') || 2.95; // lat 2.22 + body ≈ 0.73
264	  const rivZ = new THREE.Vector4(rz0, rz1, SWIM_HALF, L.floorY);
265	  // `&m08occ=1` (r8): occlusion plate for the door wall (tools/match08/occ08.py)
266	  let occTex: THREE.Texture | null = null;
267	  if (flag05('m08occ')) {
268	    occTex = await new THREE.TextureLoader().loadAsync(new URL('../../assets/textures/match08/occ08_door.png', import.meta.url).href);
269	    occTex.colorSpace = THREE.NoColorSpace; occTex.minFilter = THREE.LinearMipmapLinearFilter; occTex.anisotropy = 8;
270	  }
271	  // `&m08towelm=1` (r8): towel outline mask (tools/match08/towelmask08.py); only the towel material switches it on
272	  let tMaskTex: THREE.Texture | null = null;
273	  if (flag05('m08towelm')) {
274	    tMaskTex = await new THREE.TextureLoader().loadAsync(new URL('../../assets/textures/match08/towel08_mask.png', import.meta.url).href);
275	    tMaskTex.colorSpace = THREE.NoColorSpace;
276	  }
277	  const mat = (fallback: string, patch: THREE.Texture, k: number, fillMode = 0, swimMode = 0) => new THREE.ShaderMaterial({
278	    vertexShader: VERT, fragmentShader: FRAG, side: THREE.DoubleSide, fog: false,
279	    uniforms: { ...shared, uFallback: { value: new THREE.Color(fallback) }, uPatch: { value: patch }, uPatchK: { value: k },
280	      uFill: { value: fillTex ?? patch }, uFillMode: { value: fill ? fillMode : 0 }, uFillSize: { value: fillSize },
281	      uDrum: { value: new THREE.Vector3(L.chamber.cx, L.chamber.cy, L.chamber.r) },
282	      uSwim: { value: swimOn ? swimMode : 0 }, uRiv: { value: rivTex }, uRivZ: { value: rivZ },
283	      uOcc: { value: occTex ?? plate }, uOccOn: { value: 0 }, uTMask: { value: tMaskTex ?? plate }, uTMaskOn: { value: 0 },
284	      uClipIn: { value: new THREE.Vector4(0, 0, 0, 0) }, uClipOut: { value: new THREE.Vector4(0, 0, 0, 0) },
285	      uCeil: { value: new THREE.Vector4(0, 0, 0, 0) }, uCeilW: { value: new THREE.Vector4(0, 1, 0, 1) } },
286	  });
287	  // patch scale: wall slots ≈ 2.4 u per patch, gold band ≈ 1.2 u, towel ≈ 1 u
288	  const M = { wall: mat('#c25bd0', pWall, 1 / 2.4), drum: mat('#c25bd0', pWall, 1 / 2.4, 1), disc: mat('#c25bd0', pWall, 1 / 2.4, 2), floor: mat('#9c55c8', pWall, 1 / 2.4, 0, 1), gold: mat('#e8a24a', pGold, 1 / 1.2), plat: mat('#b78ad6', pWall, 1 / 2.4), towel: mat('#6c3bc4', pTowel, 1 / 1.0) };
289	
290	  if (tMaskTex) M.towel.uniforms.uTMaskOn.value = 1;
291	  const group = new THREE.Group();
292	  group.name = 'match08_projection';
293	  const add = (g: THREE.BufferGeometry, m: THREE.Material, name: string) => { const o = new THREE.Mesh(g, m); o.name = 'm08_' + name; group.add(o); return o; };
294	  const C = L.chamber;
295	
296	  // Scenery-in-motion round (2026-11-17, qa/match/08/scenery/NOTES.md). Every proxy surface shows exactly the approved
297	  // picture from the approved view (projection), so the near proxies can be reshaped / enlarged ABOUT THE APPROVED
298	  // VIEWPOINT without changing that view; only what a moving camera sees changes.
299	  //  `&m08lane=1`: inlet pipe + gold arch scaled ×LANE_K about the approved viewpoint (same picture, a wider swim lane:
300	  //   the fitted pipe left only ±1.35 u of water at the waterline, Benny steers to ±1.85 u + his body) and the pipe's
301	  //   lower half squared off (walls rise from the water at the lane edge instead of curving into it).
302	  //  `&m08bw=1`: the chamber's entrance wall sits flush behind the gold arch (was 3.6 u further in, where it rose out
303	  //   of the painted river and showed a stretched second copy of river / wall when riding forward).
304	  const fixLane = flag05('m08lane'), fixArch = !fixLane && flag05('m08arch'), fixBw = flag05('m08bw') || fixLane || fixArch;
305	  // `&m08arch=1` (scenery round r6): inlet pipe, gold arch and entrance wall pushed AWAY from the approved viewpoint
306	  // along the projector's own rays (×ARCH_K = 2.6), so the approved view stays the same picture while the camera, which
307	  // passed only ~0.4 u inside the fitted arch ring when steering, gets ~2 u of room. Uniform ×ARCH_K keeps the ring a
308	  // ring (a floor cap bent it toward the camera). The lowest band at the water stays where it was fitted (the arch's
309	  // bottom sill covers Benny's underside exactly as painted), ramping to ×ARCH_K by 0.9 u above the floor; pushed parts
